export async function reverseStockAdjustment(service: IGoogleSheetsService, value: unknown) {
    inputObject(value);
    const id = field(value.id, 150), note = field(value.note, 500);
    if (!id || !note)
        throw new StockAdjustmentError("Select an adjustment and enter a reversal reason.");
    const records = await listStockAdjustments(service), original = records.find(a => a.id === id);
    if (!original)
        throw new StockAdjustmentError("Adjustment not found.", 404);
    if (original.reason === "reversal")
        throw new StockAdjustmentError("A reversal cannot itself be reversed. Record a new adjustment instead.");
    const existing = records.find(a => a.reversesId === id);
    if (existing)
        return existing;
    const reversal: StockAdjustment = { ...original, id: `REV-${id}`, direction: original.direction === "out" ? "in" : "out", reason: "reversal", reversesId: id, replacesId: "", note, createdAt: new Date().toISOString(), createdBy: "web-owner" };
    await append(service, reversal);
    return reversal;
}

