import type {
  GoogleSheetRow,
  IGoogleSheetsService,
} from "@/externals/google/sheet";
import { DETAIL_HEADERS, ensureHeader, MASTER_HEADERS } from "./state";
import { isValidMovementQuantity, parseQuantity } from "@/features/backend/line/services/movements/utils";

export class MovementQuantityRequiredError extends Error {
  constructor() {
    super("Set a quantity greater than 0 for every item before marking delivered.");
    this.name = "MovementQuantityRequiredError";
  }
}

export type MovementStatus = "in_progress" | "created" | "delivered";

export type ProductMovementRecord = {
  movementId: string;
  movementMasterId: string;
  shopName: string;
  quantity: string;
  remark: string;
  fromLocation: string;
  toLocation: string;
  productImageUrl: string;
  purchaseDetailId: string;
  status: "created" | "delivered";
  createdAt: string;
  updatedAt: string;
  stockCounted: boolean;
  isNewArrival: boolean;
};

export type ProductMovementMasterRecord = {
  id: string;
  userId: string;
  packingDate: string;
  deliverDateTime?: string;
  status: MovementStatus;
  totalQuantity: string;
  createdAt: string;
  updatedAt: string;
  itemCount: number;
  shopQuantities: Record<string, number>;
};

export type MovementDateFilter = {
  date?: string;
  fromDate?: string;
  toDate?: string;
};

export async function listMovements({
  filter,
  googleSheetsService,
}: {
  filter: MovementDateFilter;
  googleSheetsService: IGoogleSheetsService;
}): Promise<ProductMovementMasterRecord[]> {
  await Promise.all([
    ensureHeader(googleSheetsService.movementMasters, MASTER_HEADERS, "H"),
    ensureHeader(googleSheetsService.movementDetails, DETAIL_HEADERS, "N"),
  ]);
  const [masterRows, detailRows] = await Promise.all([
    googleSheetsService.movementMasters.readRows("A2:H"),
    googleSheetsService.movementDetails.readRows("A2:N"),
  ]);
  const detailsByMaster = new Map<string, ProductMovementRecord[]>();
  for (const row of detailRows) {
    const detail = rowToMovement(row);
    if (!detail.movementId || !detail.movementMasterId) continue;
    detailsByMaster.set(detail.movementMasterId, [
      ...(detailsByMaster.get(detail.movementMasterId) || []),
      detail,
    ]);
  }

  return masterRows
    .map((row) =>
      rowToMovementMaster(row, detailsByMaster.get(cell(row[0])) || []),
    )
    .filter((record) => record.id && matchesDateFilter(record, filter));
}

export async function getMovementItems({
  googleSheetsService,
  movementMasterId,
}: {
  googleSheetsService: IGoogleSheetsService;
  movementMasterId: string;
}): Promise<ProductMovementRecord[]> {
  await ensureHeader(googleSheetsService.movementDetails, DETAIL_HEADERS, "N");
  const normalizedId = movementMasterId.toUpperCase();
  return (await googleSheetsService.movementDetails.readRows("A2:N"))
    .map(rowToMovement)
    .filter(
      (record) =>
        record.movementId &&
        record.movementMasterId.toUpperCase() === normalizedId,
    );
}

export async function movementExists({
  googleSheetsService,
  movementMasterId,
}: {
  googleSheetsService: IGoogleSheetsService;
  movementMasterId: string;
}): Promise<boolean> {
  const rows = await googleSheetsService.movementMasters.readRows("A2:A");
  return rows.some((row) => cell(row[0]).toUpperCase() === movementMasterId.toUpperCase());
}

export async function deleteMovementItem({
  googleSheetsService,
  movementId,
  movementMasterId,
}: {
  googleSheetsService: IGoogleSheetsService;
  movementId: string;
  movementMasterId: string;
}): Promise<ProductMovementRecord[]> {
